let keys={},joy={x:0,y:0},pointer=null,last=0,phase='',inventorySignature='',selected='water',pending=null,dialogType=null,resumeAfterLog=false,previousFocus=null,toastUntil=0,equipmentSignature='',characterSignature='',sidebarTab='equipment',medicalSelection={},medicalFeedback='',labPane='craft';
const gunIds=Object.keys(RECIPES);
const startId=id=>'start'+id[0].toUpperCase()+id.slice(1);
const currentGun=()=>run.state==='menu'&&!run.runActive?{type:'normal',level:0,rank:0}:run.lab.gun;
