const stockText=stock=>Object.entries(stock).filter(([,n])=>n>0).map(([id,n])=>`${MATERIALS[id].formula} ×${n}`).join(' · ')||'无';
const gameAudio=new GameAudio();
function syncSound(){const enabled=gameAudio.enabled;$('soundOff').classList.toggle('hidden',enabled);$('sound').setAttribute('aria-label',enabled?'关闭音效':'开启音效');$('sound').setAttribute('aria-pressed',String(enabled));$('sound').setAttribute('title',enabled?'音效已开启 · 点击静音':'音效已静音 · 点击开启')}
syncSound();
const campaignShell=new CampaignShell({run,profile,$,startMission,goBase:menu,showDialog,closeDialog,openArchive,onSound:()=>{gameAudio.setEnabled(!gameAudio.enabled);syncSound()},soundEnabled:()=>gameAudio.enabled,onEquipmentTest:openEquipmentTest,onDropMode:toggleDropMode,onRestore:()=>{phase='';inventorySignature='';equipmentSignature='';characterSignature='';campaignShell.signature='';setSidebarTab('equipment');clearInput();sync()}});
function clearInput(){keys={};joy={x:0,y:0};pointer=null;$('stick').style.transform='translate(0,0)'}
function toast(message){$('toast').textContent=message;$('toast').classList.remove('hidden');toastUntil=performance.now()+2100}
function start(){return startMission(run.runActive?run.missionId:'training',run.quick)}
function cancelCharacter(){if(run.cancelCharacterSelection()){phase='';sync();$('start')?.focus?.({preventScroll:true})}}
function startMission(id,quick=false,characterId=null){if(id==='training'&&!run.runActive&&!characterId){if(!run.beginCharacterSelection({quick}))return false;closeDialog(false);clearInput();phase='';$('screenOverlay').scrollTop=0;sync();return true}globalThis.scrollTo?.(0,0);toastUntil=0;$('toast').classList.add('hidden');gameAudio.stop();gameAudio.unlock();setSidebarTab('equipment');clearInput();closeDialog(false);const launched=id==='training'&&!run.runActive?run.startNewRun({quick,characterId:characterId||'daqi'}):run.startMission(id,{quick});if(!launched)return false;campaignShell.quick=quick;phase='';inventorySignature='';equipmentSignature='';characterSignature='';last=performance.now();sync();$('arena').focus({preventScroll:true});gameAudio.play('start');return true}
function pause(){if(dialogType)return;if(run.state==='playing'){run.state='paused';clearInput()}else if(run.state==='paused'){run.state='playing';last=performance.now()}sync()}
function menu(){setSidebarTab('equipment');clearInput();if(['won','dead'].includes(run.state))run.returnToBase();else if(run.state!=='menu'){campaignShell.abandon();return}phase='';inventorySignature='';equipmentSignature='';sync()}
function syncBag(){const enabled=run.state==='lab',medical=enabled&&labPane==='medical';const sig=JSON.stringify([run.lab.inventory,enabled,medical]);if(sig===inventorySignature)return;inventorySignature=sig;$('materialCards').innerHTML=Object.entries(MATERIALS).map(([id,m])=>`<button class="material-card" data-add="${id}" draggable="${enabled&&!medical&&(run.lab.inventory[id]??0)>0}" style="--material:${m.color}" aria-label="${enabled?(medical?'选作医疗回收':'向炉内加入'):'背包'}${m.name}，当前${run.lab.inventory[id]??0}份" ${!enabled||!run.lab.inventory[id]?'disabled':''}><span class="material-icon">${m.formula}</span><span class="material-copy"><b>${m.name}</b><small>${m.label}${enabled?(medical?' · 选作回收':' · 点击投料'):''}</small></span><span class="material-count"><small>×</small>${run.lab.inventory[id]??0}</span></button>`).join('');$('inventoryTotal').textContent=`${Object.values(run.lab.inventory).reduce((a,b)=>a+b,0)} 份`;$('bagHint').textContent=enabled?(medical?'点击加入医疗交易选择；确认前不会消耗。':'拖到炉内或点击投料；炉内物质点击可取回。'):'击败怪物，靠近拾取。未捡物质关末清除。'}
function syncGun(){const gun=currentGun(),s=run.state==='menu'&&!run.runActive?gunStats(gun,run.abilities):run.stats,recipe=RECIPES[gun.type];$('gunName').textContent=gunName();$('gunLevel').textContent=gun.type==='normal'?'基础型 / LV. 0':`${recipe.family} / LV. ${gun.level} · 进阶 +${gun.rank||0}`;$('gunIcon').style.color=recipe?.color||'#a9bda0';$('statDamage').textContent=Number(s.damage.toFixed(1));$('statRange').textContent=s.range;$('statRate').textContent=`${(1/s.interval).toFixed(1)}/s`;$('statEffectLabel').textContent='枪型效果';$('statBurn').textContent=gun.type==='flame'?`灼烧 ${Number((s.burnDps||0).toFixed(1))}/s`:gun.type==='acid'?`腐蚀 ${Math.round((s.corrosionStrength??0)*100)}%/层`:gun.type==='gas'?`击退 ${s.knockback??'—'}`:gun.type==='electric'?`连锁 ${s.chainCount??'—'}`:gun.type==='iron'?`贯穿 ${s.pierce??'—'}`:gun.type==='water'?'直线水柱':'普通弹';$('gunDescription').textContent=recipe?recipe.effect+' '+evolutionDescription(gun):'一把可靠的普通枪。先活下来，再想办法变强。'}

function statText(value,unit){return unit==='%'?`${Math.round(value*100)}%`:unit==='×'?`${value.toFixed(2)}×`:`${Number(value.toFixed(1))}${unit}`}
function syncCharacter(){
 const a=run.abilities,p=run.experienceProgress,hp=Number(run.hp.toFixed(1)),signature=JSON.stringify([p,hp,run.diamonds,a,run.characterId]);if(signature===characterSignature)return;characterSignature=signature;
 const roleBase=characterBaseAbilities(run.characterId);
 const row=(label,key,unit='')=>{const boost=key==='damage'?(run.attackMultiplier||1):1,value=a[key]*boost,base=roleBase[key]*boost,delta=value-base,format=n=>statText(n,unit);return `<span>${label} <b>${format(value)}</b><small>基础 ${format(base)} · 升级 ${delta>=0?'+':'−'}${format(Math.abs(delta))}</small></span>`};
 $('abilityStats').innerHTML=`${run.character?`<div class="participant-identity"><b>${run.character.name}</b><span>${run.character.profession}</span><small>擅长 ${run.character.specialty}</small>${characterTraitsHtml(run.characterId)}</div>`:''}<div class="section-label">角色属性 <span>LV.${p.level} · ◇${run.diamonds}</span></div><div class="character-vitals"><span>当前生命</span><strong>${hp} / ${a.maxHp}</strong><div class="character-health" role="progressbar" aria-label="当前生命" aria-valuemin="0" aria-valuemax="${a.maxHp}" aria-valuenow="${hp}"><i style="width:${Math.max(0,Math.min(100,hp/a.maxHp*100))}%"></i></div></div><div class="character-progress"><span>经验 <b>${p.current} / ${p.needed}</b></span><span>待选能力 ${p.pending}</span></div><p class="character-note">能力在关间选择后生效，待选次数尚未计入属性。</p><h3>生存</h3><div class="character-grid">${row('最大生命','maxHp')}${row('防御减伤','defense','%')}${row('闪避率','dodge','%')}${row('生命恢复','regen','/s')}</div><h3>火力</h3><div class="character-grid">${row('基础伤害','damage')}${row('攻速倍率','attackSpeed','×')}${row('暴击率','crit','%')}<span>暴击伤害 <b>2×</b><small>直接命中触发</small></span></div><h3>行动</h3><div class="character-grid">${row('移动速度','speed')}${row('拾取范围','magnet')}</div><p class="character-note">角色能力本局保留，换枪不清零。${run.attackMultiplier>1?'当前快速测试攻击×100；正常成长会进入下一幕。':''}单把枪的实际伤害、射速与配件请查看「装备」。闪避不适用于Boss技能。</p>`
}
function chooseAbility(id){if(dialogType||!run.chooseAbility(id))return;phase='';clearInput();sync();gameAudio.play('level')}
function toggleDropMode(){if(run.setDropMode(run.dropMode==='standard'?'high':'standard')){phase='';sync()}}

function setSidebarTab(tab){sidebarTab=tab;for(const [key,pane,button] of [['equipment','equipmentPane','sidebarEquipment'],['character','characterPane','sidebarCharacter'],['bag','backpack','sidebarBag'],['recipes','recipesPane','sidebarRecipes']]){const active=key===tab;$(pane).classList.toggle('hidden',!active);$(button).setAttribute('aria-selected',String(active));$(button).setAttribute('tabindex',active?'0':'-1')}}
function browseRecipe(direction){if(run.state!=='lab'||dialogType||labPane!=='craft')return;selected=gunIds[(gunIds.indexOf(selected)+direction+gunIds.length)%gunIds.length];syncLab()}
$('prevRecipe').onclick=()=>browseRecipe(-1);$('nextRecipe').onclick=()=>browseRecipe(1);$('sidebarEquipment').onclick=()=>setSidebarTab('equipment');$('sidebarCharacter').onclick=()=>setSidebarTab('character');$('sidebarBag').onclick=()=>setSidebarTab('bag');$('sidebarRecipes').onclick=()=>setSidebarTab('recipes');
const sidebarKeys=['equipment','character','bag','recipes'],sidebarButtons=['sidebarEquipment','sidebarCharacter','sidebarBag','sidebarRecipes'];for(const [index,id] of sidebarButtons.entries())$(id).addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();e.stopPropagation();const count=sidebarKeys.length,next=e.key==='Home'?0:e.key==='End'?count-1:(index+(e.key==='ArrowRight'?1:count-1))%count;setSidebarTab(sidebarKeys[next]);$(sidebarButtons[next]).focus()});
function syncRecipes(){const isLab=run.state==='lab',owned=run.weapons.filter(w=>w.gun&&Object.hasOwn(RECIPES,w.gun.type));$('recipeCount').textContent=`${owned.length} / ${gunIds.length} OWNED`;$('recipeCards').innerHTML=Object.entries(RECIPES).map(([id,r])=>{const gun=owned.find(w=>w.gun.type===id)?.gun,affordable=Object.entries(r.cost).every(([k,n])=>(run.lab.inventory[k]??0)+(run.lab.furnace[k]??0)>=n),status=!gun?'未持有 · 战斗中拾取':gun.level>=MAX_LEVEL?'已满级 · 可查看配方':!isLab?'已持有 · 关间可升级':affordable?'材料充足 · 选择升级配方':'材料不足 · 仍可查看配方';return `<button class="recipe-card ${id===selected?'selected':''}" data-recipe="${id}" ${!isLab?'disabled':''}><div class="recipe-head"><b>${r.name}</b><span class="${id==='flame'?'flame-tag':''}">${r.tag}</span></div><p>${stockText(r.cost)}</p><small>${status}</small></button>`}).join('')}
function setLabPane(pane){labPane=pane;$('labCraftPane').classList.toggle('hidden',pane!=='craft');$('medicalRoom').classList.toggle('hidden',pane!=='medical');$('labCraftTab').setAttribute('aria-pressed',String(pane==='craft'));$('labMedicalTab').setAttribute('aria-pressed',String(pane==='medical'));syncBag();if(pane==='medical')syncMedical()}
function syncMedical(){if(run.state!=='lab')return;for(const id of Object.keys(medicalSelection))medicalSelection[id]=Math.min(medicalSelection[id],run.lab.inventory[id]||0);const q=treatmentQuote(run,medicalSelection),cost=RECIPES[run.lab.gun.type]?.cost||{};$('labMedicalTab').textContent=`医疗室 · ${q.cost}份 / 5HP`;$('medicalHp').textContent=`生命 ${Number(run.hp.toFixed(1))} / ${run.abilities.maxHp}`;$('medicalPrice').textContent=`本关价 ${q.cost} 份物资 → +5 HP`;$('medicalPreview').textContent=q.healing===0?'已满血，不接受无效交易。':`本次实际恢复 ${Number(q.healing.toFixed(1))} 点，治疗后 ${Number(q.after.toFixed(1))} HP。${q.healing<5?'恢复不足5点，仍按完整价格收费。':''}`;$('medicalMaterials').innerHTML=Object.entries(MATERIALS).map(([id,m])=>{const n=medicalSelection[id]||0,available=run.lab.inventory[id]||0;return `<div class="medical-material"><span style="color:${m.color}">${m.formula}</span><div><b>${m.name}</b><small>背包 ${available}份${Object.hasOwn(cost,id)?' · 当前枪升级材料，建议保留':''}</small></div><button data-med-minus="${id}" aria-label="少选一份${m.name}" ${n<=0?'disabled':''}>−</button><strong>${n}</strong><button data-med-plus="${id}" aria-label="多选一份${m.name}" ${n>=available||q.total>=q.cost||q.healing<=0?'disabled':''}>＋</button><button class="medical-add-all" data-med-all="${id}" aria-label="尽量选入${m.name}补足本次治疗" ${n>=available||q.total>=q.cost||q.healing<=0?'disabled':''}>＋全部</button></div>`}).join('');$('medicalSelected').textContent=`已选 ${q.total} / ${q.cost} 份`;$('medicalBuy').disabled=!q.ok;$('medicalBuy').textContent=q.healing===0?'满血，无需治疗':`支付 ${q.cost} 份所选物资，恢复 ${Number(q.healing.toFixed(1))} HP`;$('medicalClear').disabled=q.total===0;$('medicalFeedback').textContent=medicalFeedback||(!q.ok&&q.reason==='quantity'?`还需选择 ${Math.max(0,q.cost-q.total)} 份物资。`:'请核对消耗，再确认交易。')}
$('labCraftTab').onclick=()=>setLabPane('craft');$('labMedicalTab').onclick=()=>setLabPane('medical');$('medicalClear').onclick=()=>{medicalSelection={};medicalFeedback='已清空选择，未消耗物资。';syncMedical()};
$('medicalMaterials').addEventListener('click',e=>{if(run.state!=='lab'||dialogType)return;const plus=e.target.closest('[data-med-plus]'),minus=e.target.closest('[data-med-minus]'),all=e.target.closest('[data-med-all]');if(!plus&&!minus&&!all)return;const id=plus?.dataset.medPlus||minus?.dataset.medMinus||all?.dataset.medAll;if(!Object.hasOwn(MATERIALS,id))return;const q=treatmentQuote(run,medicalSelection),n=medicalSelection[id]||0;if(plus&&q.healing>0&&q.total<q.cost&&n<(run.lab.inventory[id]||0))medicalSelection[id]=n+1;if(minus&&n>0)medicalSelection[id]=n-1;if(all&&q.healing>0)medicalSelection[id]=n+Math.max(0,Math.min((run.lab.inventory[id]||0)-n,q.cost-q.total));medicalFeedback='';syncMedical()});
$('medicalBuy').onclick=()=>{if(dialogType)return;const result=run.buyTreatment(medicalSelection);if(!result.ok){medicalFeedback='交易条件不足，未扣除物资。';syncMedical();return}medicalSelection={};medicalFeedback=`交易完成：消耗 ${result.cost} 份，实际恢复 ${Number(result.healed.toFixed(1))} 点生命。`;sync();syncLab();gameAudio.play('heal')};
function syncLab(){
 syncMedical();const at=gunIds.indexOf(selected),l=run.lab,r=RECIPES[selected],info=l.recipeInfo(selected),matches=l.gun.type===selected&&!l.gun.empty,heldIndex=run.weapons.findIndex(w=>w.gun?.type===selected),empty=!!l.gun.empty;
 $('recipePosition').textContent=`${at+1} / ${gunIds.length}`;$('recipeSelection').textContent=empty?'空枪槽 · 等待拾取化学枪':matches?'当前持枪 · 同系升级':'查看升级配方 · 枪械通过掉落获得';syncBag();syncGun();syncRecipes();
 $('furnaceContents').innerHTML=Object.entries(l.furnace).filter(([,n])=>n>0).map(([id,n])=>`<button class="furnace-chip" data-remove="${id}" draggable="true" aria-label="取回一份${MATERIALS[id].name}">${MATERIALS[id].formula} ×${n}<span>−</span></button>`).join('')||'<span class="empty-furnace">升级自动扣除材料，拖拽投料可选。</span>';
 $('recipeKind').textContent=r.tag;$('recipeTitle').textContent=r.name;$('recipeNumber').textContent=r.displayFormula;$('equation').textContent=r.equation||r.assemblyText;$('scienceNote').textContent=r.fact+(selected==='flame'?' 产水进入实验收集瓶，不回流可用背包。':'');$('furnaceSymbol').textContent=r.displayFormula;$('reactorLevel').textContent=matches?Math.min(MAX_LEVEL,l.gun.level+1):'—';$('ignition').checked=l.ignition;$('ignition').disabled=selected!=='flame'||!matches;
 const missing=stockText(info.missing);$('requirements').classList.toggle('missing',!matches||!info.ready||selected==='flame'&&!l.ignition);$('requirements').textContent=!info.ready?`材料还缺：${missing}`:selected==='flame'&&!l.ignition?'需要开启炉内点火源':'材料充足 · 点击升级自动扣除，拖拽可选';$('craft').disabled=!matches||!info.ready||selected==='flame'&&!l.ignition;$('craft').innerHTML=`升级${r.name} · Lv.${l.gun.level+1} <span>↗</span>`;
 if(!matches){$('craft').textContent=empty?'空枪槽 · 等待拾取':heldIndex>=0?`请切换枪槽 ${heldIndex+1} 升级`:`未持有${r.name} · 等待掉落`;$('requirements').textContent=empty?'此槽没有化学枪，请在战斗中拾取；材料只能升级已持有的枪。':heldIndex>=0?`${r.name}已装备在枪槽 ${heldIndex+1}，请切换到对应枪槽升级。`:'尚未持有这把枪，请在战斗中拾取。配方可查看，不能制造或换系。'}
 if(matches&&info.maxed){$('craft').disabled=true;$('craft').textContent=`已达本原型上限 · Lv.${MAX_LEVEL}`;$('requirements').textContent='本系已满级，不再消耗材料；另一把枪可切换到对应槽位升级。';$('requirements').classList.remove('missing')}
 $('nextWave').disabled=false;$('nextWave').innerHTML=`装备就绪，开始第 ${run.wave+1} 关 <span>→</span>`;$('returnAll').disabled=Object.values(l.furnace).every(n=>n===0);$('supplyNote').classList.remove('hidden');$('supplyNote').textContent='背包保留已拾取的物质；未拾取物质已在关末清除。';$('scienceTip').textContent=r.fact;
}
function move(id,to){if(run.state!=='lab'||dialogType)return;if(labPane==='medical'&&to==='furnace'){const q=treatmentQuote(run,medicalSelection),n=medicalSelection[id]||0;if(q.healing>0&&q.total<q.cost&&n<(run.lab.inventory[id]||0)){medicalSelection[id]=n+1;medicalFeedback='';syncMedical()}return}if(run.lab.moveMaterial(id,to)){syncLab();gameAudio.play('click')}}
function requestCraft(){if(run.state!=='lab'||dialogType)return;completeCraft(run.craft(selected),selected)}
function completeCraft(result,id){if(!result.ok){$('labFeedback').textContent=result.reason==='other-slot'?'另一枪槽已持有这把枪，请切换到对应槽位升级。':result.reason==='not-owned'?'先在战斗中拾取这把化学枪，实验室只能升级已持有的枪。':'条件尚未满足，请检查材料数量和点火源。';return}gameAudio.play('craft');const r=RECIPES[id];$('labFeedback').textContent=`${r.name} Lv.${run.lab.gun.level} 已就绪。${id==='flame'?'反应产水 2 份已记入收集瓶。':''}剩余材料已退回背包。`;syncLab()}
function showDialog(type,html){if(!dialogType)previousFocus=document.activeElement;dialogType=type;$('dialogCard').innerHTML=html;$('dialogOverlay').classList.remove('hidden');$('dialogCard').querySelector('button')?.focus({preventScroll:true})}
function closeDialog(restore=true){$('dialogOverlay').classList.add('hidden');if(dialogType==='log'&&resumeAfterLog){run.state='playing';last=performance.now()}resumeAfterLog=false;dialogType=null;pending=null;if(restore)previousFocus?.focus?.({preventScroll:true});sync()}
function openArchive(){if(dialogType)return;resumeAfterLog=run.state==='playing';if(resumeAfterLog){run.state='paused';clearInput();sync()}showDialog('log',campaignShell.archiveHtml());$('closeArchive').onclick=()=>closeDialog()}
function openLog(){if(dialogType)return;resumeAfterLog=run.state==='playing';if(resumeAfterLog){run.state='paused';clearInput();sync()}showDialog('log',`<div class="eyebrow">DISCOVERY LOG / 本局图鉴</div><h2>把发现，留在这里。</h2><div class="log-entry"><h3>元素与组成</h3><p>${Object.entries(ELEMENTS).map(([symbol,name])=>`${symbol} · ${name}`).join('　')}</p><p>元素符号描述组成；HCl(aq)表示盐酸中的溶质，NaCl表示离子组成比，电弧能量由枪械电源提供。</p></div>${Object.entries(MATERIALS).map(([id,m])=>`<div class="log-entry"><h3>${m.formula} · ${m.name}</h3><p>${m.fact}</p></div>`).join('')}<div class="log-entry"><h3>本局已制作</h3><p>${run.lab.discoveries.length?run.lab.discoveries.map(id=>RECIPES[id].name).join('、'):'尚未完成改装；第一波结束后进入实验室。'}</p></div>${run.lab.discoveries.includes('flame')?`<div class="log-entry"><h3>氢气燃烧 · 已发现</h3><p class="formula">2H₂ + O₂ → 2H₂O</p><p>条件：点火。氧气是氧化剂，空气中也存在氧气。试验产水累计 ${run.lab.products.water} 份，仅作收集记录。</p></div>`:''}${bestiaryLog(run.missionId)||`<div class="log-entry"><h3>失控实验样本</h3>${ENEMY_TYPES.slice(0,10).map(e=>`<p><strong>${e.name}</strong> · ${e.description} · ◇${e.diamonds}</p>`).join('')}<p>这些是化学概念的虚构拟人化；掉落为回收实验物资，不代表怪物死亡的真实化学反应。</p></div>`}<div class="log-entry"><h3>化学事实与游戏效果</h3><p>水柱、灼烧、腐蚀增伤、气压击退、电弧连锁、铁弹贯穿与不限弹药均属于游戏机制；不代表物质的全部现实性质或实际实验操作。隐藏配方后续加入。</p></div><button class="cancel" id="cancelDialog">返回${resumeAfterLog?'战斗':'实验'}</button>`);paintBestiaryPreviews($('dialogCard'),run.missionId);$('cancelDialog').onclick=()=>closeDialog()}
function syncEquipment(){
 run.saveWeapon();const sig=JSON.stringify([run.selectedWeapon,run.weapons.map(w=>[w.gun,w.attachments,w.muzzle])]);const chooser=prefix=>run.weapons.map((w,i)=>`<button id="${prefix}${i}" aria-pressed="${run.selectedWeapon===i}"><small>枪槽 ${i+1}</small><b>${w.gun?weaponName(w.gun):'空槽'}</b></button>`).join('');

 if(sig!==equipmentSignature){equipmentSignature=sig;$('weaponSwitcher').innerHTML=chooser('viewGun');$('labWeapons').innerHTML=chooser('labGun');for(const prefix of ['viewGun','labGun'])[0,1].forEach(i=>{$(prefix+i).onclick=()=>{run.selectWeapon(i);equipmentSignature='';syncEquipment();syncGun();if(run.state==='lab'){selected=RECIPES[run.lab.gun.type]?run.lab.gun.type:'water';syncLab()}}});$('equipmentSlots').innerHTML=run.weapons.map((w,wi)=>`<section class="weapon-rack ${run.selectedWeapon===wi?'rack-selected':''}"><button class="rack-select" id="weaponSlot${wi}"><span>枪槽 ${wi+1}${run.selectedWeapon===wi?' · 当前查看 / 改装':''}</span><strong>${w.gun?weaponName(w.gun):'空武器槽'}</strong><small>${w.gun?`Lv.${w.gun.level} · 进阶 +${w.gun.rank||0}`:'拾取不同化学枪后自动装入'}</small></button>${[0,1].map(i=>{const id=w.attachments[i],a=ACCESSORIES[id],active=a&&a.gun===w.gun?.type;return `<div class="gear-slot"><b>⚙ 配件 ${i+1} · ${a?a.name:'空槽'}</b><small>${a?(active?'生效 · '+a.description:'未生效 · 需要'+RECIPES[a.gun].name):'精英掉落 · 收纳后关间安装'}</small><div class="gear-meter" id="gearMeter${wi}_${i}" role="progressbar" aria-label="枪槽${wi+1}配件${i+1}进度" aria-valuemin="0" aria-valuemax="100"><i id="gearFill${wi}_${i}"></i></div><small id="gearCharge${wi}_${i}"></small></div>`}).join('')}<div class="gear-slot muzzle-slot"><b>⑂ 枪口 · ${w.muzzle?MUZZLES[w.muzzle].name:'空槽'}</b><small>${w.muzzle?MUZZLES[w.muzzle].description:'所有枪型通用 · Boss掉落'}</small></div></section>`).join('');[0,1].forEach(wi=>{$('weaponSlot'+wi).onclick=()=>{run.selectWeapon(wi);equipmentSignature='';syncGun();syncEquipment();if(run.state==='lab'){selected=RECIPES[run.lab.gun.type]?run.lab.gun.type:'water';syncLab()}}})}
 run.weapons.forEach((w,wi)=>[0,1].forEach(i=>{const id=w.attachments[i],a=ACCESSORIES[id],active=a&&a.gun===w.gun?.type,passive=id==='rail';let value=id==='condenser'?w.condenser.charge:(w.accessoryCharge[id]||0),label='蓄力';if(id==='conductive'){const cooldown=waterChainCooldown(run);value=Math.max(0,Math.min(1,1-((w.waterChainReady||0)-run.elapsed)/cooldown));label=value>=1?'就绪 · 命中触发':'充电'}if(id==='condenser')label=w.condenser.spraying?'喷水消耗中':'蓄水';if(id==='magnetic'&&w.magneticTime>0){value=w.magneticTime/3;label='护环生效中'}const percent=Math.max(0,Math.min(100,Math.floor(value*100))),suffix=wi+'_'+i;$('gearMeter'+suffix).classList.toggle('hidden',!active||passive);$('gearFill'+suffix).style.width=(active?percent:0)+'%';$('gearMeter'+suffix).setAttribute('aria-valuenow',String(active?percent:0));$('gearMeter'+suffix).setAttribute('aria-valuetext',!active?'未生效':passive?'持续生效':label+' '+percent+'%');$('gearMeter'+suffix).classList.toggle('releasing',id==='condenser'&&w.condenser.spraying||id==='magnetic'&&w.magneticTime>0);$('gearCharge'+suffix).textContent=!id?'':!active?'未生效 · 武器不适配':passive?'持续生效 · 铁弹加速':label+' '+percent+'%'}))
}
const lootIcons={condenser:'◒',heat:'♨',conductive:'ϟ',freeze:'❄',foam:'◌',hydrogen:'H₂',pressure:'◎',expansion:'❋',capacitor:'▥',magnetic:'⊕',rail:'⇉',shards:'✧',focus:'⊙',spread:'⋔',rapid:'»',fork:'⑂'};
function intermissionHeading(){return run.intermissionActive?`<div class="intermission-progress">第 ${run.wave} 关完成 · 待选能力 ${run.pendingAbilityCount} · 待整备 ${run.pendingLoot.length+(['reward','gunReward'].includes(run.state)?1:0)}</div>`:''}
function renderReward(card){const muzzle=run.rewardKind==='muzzle',catalog=muzzle?MUZZLES:ACCESSORIES;card.innerHTML=`${intermissionHeading()}<div class="loot-heading"><span class="loot-emblem">${muzzle?'⑂':'⚙'}</span><div class="eyebrow">${muzzle?'BOSS TROPHY / 枪口改装':'ELITE TROPHY / 枪械配件'}</div><h2>${muzzle?'改造你的<span>主火力。</span>':'给枪装上<span>新能力。</span>'}</h2><p>${muzzle?'独立枪口槽 · 所有枪通用':'两把枪 · 四个配件槽 · 关间自行选择位置'}</p></div><div class="loot-options">${run.rewardChoices.map((id,i)=>{const a=catalog[id],compatible=muzzle||run.weapons.some(w=>w.gun?.type===a.gun);return `<button class="loot-card" id="reward${i}" style="--loot-color:${muzzle?'#86dcf2':RECIPES[a.gun].color}"><span class="loot-category">${muzzle?'枪口组件':'机械配件'} · ${String(i+1).padStart(2,'0')}</span><span class="loot-art">${lootIcons[id]}</span><strong>${a.name}</strong><p>${a.description}</p><span class="loot-fit ${compatible?'':'inactive'}">${muzzle?'通用 · 独立枪口槽':compatible?'✓ 适配持有武器':'需'+RECIPES[a.gun].name+' · 当前不生效'}</span><small>免费战利品 · 按 ${i+1} 安装</small></button>`}).join('')}</div><p class="loot-footer">${muzzle?'选择任一枪槽安装枪口。':'选择四个配件槽中的一个安装，可替换已有配件。'}不消耗钻石。放弃可恢复最多50点生命。</p><button id="skipReward" class="back-link">放弃本次战利品，${run.hp<run.abilities.maxHp?'恢复 '+Number(Math.min(50,run.abilities.maxHp-run.hp).toFixed(1))+' HP':'已满血'}</button>`;run.rewardChoices.forEach((id,i)=>{$('reward'+i).onclick=()=>selectReward(id)});$('skipReward').onclick=()=>{const before=run.hp;if(run.chooseReward(null)){phase='';sync();toast(`放弃战利品 · 恢复 ${Number((run.hp-before).toFixed(1))} 点生命`)}}}
function selectReward(id){openInstallation({run,id,$,showDialog,closeDialog,icons:lootIcons,onInstalled:()=>{phase='';equipmentSignature='';sync()}})}
function renderGunPickup(card){card.innerHTML=`${intermissionHeading()}<div class="eyebrow">WEAPON FOUND / 化学枪</div><h2>发现<span>${RECIPES[run.pendingGun].name}</span></h2><p>两把枪已齐，选择要替换的武器。该槽的Lv与进阶将清零，配件和枪口留下。</p><div class="gun-swap-options">${run.weapons.map((w,i)=>`<button id="swapGun${i}" class="cancel">替换枪槽${i+1}：${weaponName(w.gun)} · Lv.${w.gun.level} / +${w.gun.rank||0}</button>`).join('')}</div><button id="skipGun" class="back-link">放弃这把枪，保留当前双枪</button>`;[0,1].forEach(i=>{$('swapGun'+i).onclick=()=>{run.resolveGunPickup(i);phase='';syncGun();sync()}});$('skipGun').onclick=()=>{run.resolveGunPickup(null);phase='';sync()}}
function openEquipmentTest(){if(run.runActive){toast('本局进行中，装备试验不会覆盖当前装备');return}showDialog('test',`<h2>双枪与进阶试验</h2><p>直接测试 +3 / +6 形态；正常开局仍是普通枪。Lv由物质升级，+阶由同名掉枪增加。</p><label>关卡 <select id="testWave">${Array.from({length:10},(_,i)=>`<option value="${i+1}">第${i+1}关</option>`).join('')}</select></label>${[0,1].map(wi=>`<fieldset><legend>枪槽 ${wi+1}</legend><label>枪型 <select id="testGun${wi}"><option value="${wi?'':'normal'}">${wi?'空槽':'普通枪'}</option>${gunIds.map(id=>`<option value="${id}">${RECIPES[id].name}</option>`).join('')}</select></label><label>物质升级 <select id="testGunLevel${wi}">${Array.from({length:MAX_LEVEL},(_,i)=>`<option value="${i+1}">Lv.${i+1}</option>`).join('')}</select></label><label>同名枪进阶 <select id="testRank${wi}">${Array.from({length:11},(_,i)=>`<option value="${i}">+${i}${i===3?' · 第二形态':i===6?' · 最终形态':''}</option>`).join('')}</select></label>${[0,1].map(i=>`<label>配件${i+1} <select id="testAccessory${wi*2+i}"><option value="">空槽</option>${Object.entries(ACCESSORIES).map(([id,a])=>`<option value="${id}">${a.name}（${RECIPES[a.gun].name}）</option>`).join('')}</select></label>`).join('')}<label>枪口 <select id="testMuzzle${wi}"><option value="">原版枪口</option>${Object.entries(MUZZLES).map(([id,a])=>`<option value="${id}">${a.name}</option>`).join('')}</select></label></fieldset>`).join('')}<p id="testFeedback"></p><button id="launchTest" class="primary">携带双枪进入测试</button><button id="closeTest" class="back-link">取消</button>`);$('launchTest').onclick=()=>{const types=[0,1].map(i=>$('testGun'+i).value);if(types[0]&&types[0]===types[1]){$('testFeedback').textContent='同名枪用于进阶，请给第二槽选择不同枪型。';return}const settings=[0,1].map(wi=>({type:types[wi],level:Math.max(1,Math.min(10,Number($('testGunLevel'+wi).value)||1)),rank:Math.max(0,Math.min(10,Number($('testRank'+wi).value)||0)),attachments:[0,1].map(i=>$('testAccessory'+(wi*2+i)).value||null),muzzle:$('testMuzzle'+wi).value})),wave=Math.max(1,Math.min(10,Number($('testWave').value)||1));startMission('training',false,'daqi');run.isEquipmentTest=true;for(let i=0;i<2;i++){const cfg=settings[i];if(i===0||RECIPES[cfg.type]){run.selectWeapon(i);run.lab.gun=RECIPES[cfg.type]?{type:cfg.type,level:cfg.level,rank:cfg.rank}:{type:'normal',level:0,rank:0};run.attachments=cfg.attachments.map((id,k,all)=>ACCESSORIES[id]&&all.indexOf(id)===k?id:null);run.muzzle=MUZZLES[cfg.muzzle]?cfg.muzzle:null;run.saveWeapon()}}run.selectWeapon(0);run.wave=wave;run.eliteIntroduced=[3,5,7].filter(w=>w<wave);phase='';equipmentSignature='';sync()};$('closeTest').onclick=()=>closeDialog()}
function renderResult(card,won){campaignShell.renderResult(card,won)}

function syncCondenser(){const p=run.condenser; $('condenserPanel').classList.toggle('hidden',run.dual||!run.legacy&&!run.attachments.includes('condenser'));const flame=currentGun().type==='flame';$('condenserPercent').textContent=Math.floor(p.charge*100)+'%';$('condenserFill').style.width=p.charge*100+'%';$('condenserStatus').textContent=!flame?'选择氢燃烧枪，体验喷火蓄水配件。':!p.equipped?'水包已拆下，主枪保持原样。':p.spraying?(p.collecting?'正在喷水 · 喷火同时补水':'正在喷水 · 停火只耗水'):p.collecting?'喷火 → 冷凝收集 · 满包自动侧后方喷水':p.charge>0?'等待主枪开火补水 · 蓄满才启动':'空水包已装好 · 喷火时自动蓄水';$('toggleCondenser').textContent=p.equipped?'拆下水包（试玩）':'装上空水包（试玩）';$('toggleCondenser').disabled=!run.legacy||!flame||!['playing','paused','lab'].includes(run.state);$('toggleCondenser').setAttribute('aria-pressed',String(p.equipped))}
function sync(){campaignShell.refresh();const state=run.state,lab=state==='lab',progress=run.experienceProgress;$('missionChannel').classList.add('hidden');syncCondenser();syncEquipment();syncGun();syncCharacter();$('participantName').textContent=run.character?`${run.character.name} · 生命值`:'生命值';$('hpText').textContent=`${Math.ceil(run.hp)} / ${run.abilities.maxHp}`;$('hpBar').style.width=`${run.hp/run.abilities.maxHp*100}%`;$('kills').textContent=run.kills;const finalDuel=run.missionId==='core';$('waveLabel').textContent=finalDuel?'FINAL':String(run.wave).padStart(2,'0');$('waveTotal').classList.toggle('hidden',finalDuel);const waitingForGuarantee=run.waveTime>=run.duration&&[1,3].includes(run.wave)&&!run.guaranteedGunWaves.includes(run.wave);const waitingForLoot=run.waveTime>=run.duration&&run.waitingForLoot;const t=Math.max(0,Math.ceil(run.duration-run.waveTime));$('timer').textContent=finalDuel?'∞':lab?'LAB':run.intermissionActive?'PREP':waitingForLoot?'LOOT':waitingForGuarantee?'HUNT':run.waveTime>=run.duration&&!run.specialDefeated&&waveKind(run.wave)!=='normal'?'BOSS':`${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;$('phaseLabel').textContent=({character:'选择实验员',menu:'准备实验',playing:run.wave===1?'收集阶段':'改装验证',lab:'波间实验室',paused:'实验暂停',upgrade:'关间 · 能力升级',reward:'关间 · 装备分配',gunReward:'关间 · 枪械替换',dead:'实验中止',won:'实验完成'})[state];$('phaseDot').style.background=lab?'#77d9f5':state==='dead'?'#ed8e92':'#b9e4ad';$('pause').disabled=!['playing','paused'].includes(state);$('pause').textContent=state==='paused'?'▷':'Ⅱ';$('pause').setAttribute('aria-label',state==='paused'?'继续游戏':'暂停游戏');$('playerLevel').textContent=`角色 LV.${progress.level}`;$('experienceText').textContent=`${progress.current} / ${progress.needed} ◇`;$('experienceBar').style.width=`${Math.min(100,progress.current/progress.needed*100)}%`;$('experienceHud').classList.toggle('hidden',lab);syncBag();const pending=run.pendingAbilityCount+run.pendingLoot.length;$('pendingDecisions').textContent=`关间待选：能力 ${run.pendingAbilityCount} · 装备 ${run.pendingLoot.length}`;$('pendingDecisions').classList.toggle('hidden',!pending||!['playing','paused'].includes(state));if(waitingForGuarantee)$('fieldHint').textContent='保底化学枪尚未掉落 · 击败剩余怪物';if(waitingForLoot)$('fieldHint').textContent='战利品留在场上 · 靠近收纳，关间统一选择';if(finalDuel){$('phaseLabel').textContent=run.coreDefeated?'回收 AI 核心':state==='paused'?'最终战暂停':'最终决战';$('fieldHint').textContent=run.coreDefeated?'AI 核心已掉落 · 靠近拾取，恢复通信':'最终决战 · 无时间限制 · 击败三形态首领，回收 AI 核心'}if(phase===state)return;phase=state;$('screenOverlay').classList.toggle('loot-screen',state==='reward');$('screenOverlay').classList.toggle('base-screen',state==='menu');$('screenOverlay').classList.toggle('character-screen',state==='character');$('screenOverlay').classList.toggle('campaign-result',['won','dead'].includes(state));$('screenOverlay').classList.toggle('result-win',state==='won');$('screenOverlay').classList.toggle('result-loss',state==='dead');$('screenCard').classList.toggle('result-screen',['won','dead'].includes(state));clearInput();$('labView').classList.toggle('hidden',!lab);$('stage').classList.toggle('lab-stage',lab);$('battleHud').classList.toggle('hidden',lab);$('controlsNote').classList.toggle('hidden',lab);$('screenOverlay').classList.toggle('hidden',!['character','menu','paused','upgrade','reward','gunReward','dead','won'].includes(state));$('fieldHint').textContent=finalDuel?(run.coreDefeated?'AI 核心已掉落 · 靠近拾取，恢复通信':'最终决战 · 无时间限制 · 击败三形态首领，回收 AI 核心'):lab?'材料不会凭空消失：制作只消耗配方所需，多余退回。':`第${run.wave}关 · 怪物血量 ×${(1+(run.wave-1)*.13).toFixed(2)} / 伤害 ×${(1+(run.wave-1)*.09).toFixed(2)} · ${waveKind(run.wave)==='elite'?'击败精英获得配件':run.wave>=9?'击败Boss，注意预警':'收集物质，结束后进入实验室'}`;syncGun();syncCharacter();syncRecipes();if(lab){medicalSelection={};medicalFeedback='';setLabPane('craft');selected=Object.hasOwn(RECIPES,run.lab.gun.type)?run.lab.gun.type:gunIds[0];setSidebarTab('bag');$('labFeedback').textContent='选择已持有枪械的配方进行升级；新枪需要战斗中拾取。';syncLab();$('furnace').focus({preventScroll:true});return}if(state==='playing'){$('supplyNote').classList.add('hidden');return}const card=$('screenCard');if(state==='gunReward'){renderGunPickup(card)}else if(state==='reward'){renderReward(card)}else if(state==='upgrade'){card.innerHTML=`${intermissionHeading()}<div class="eyebrow">DIAMOND UPGRADE / LV.${run.level+1} 成长分配</div><h2>进化的是你，<span>不止是枪。</span></h2><p>关间统一分配钻石经验。选择一项能力，换枪后仍然保留。</p><div class="ability-options">${run.upgradeChoices.map((id,i)=>{const d=ABILITIES[id],before=run.abilities[d.stat],after=Math.min(d.max??Infinity,before+d.step),preview=id==='health'?`生命 ${Number(run.hp.toFixed(1))}/${before} → ${Number(Math.min(after,run.hp+d.step).toFixed(1))}/${after}`:`${statText(before*(id==='damage'?(run.attackMultiplier||1):1),d.unit)} → ${statText(after*(id==='damage'?(run.attackMultiplier||1):1),d.unit)}`;return `<button class="ability-option" id="ability${i}"><span>${d.icon}</span><strong>${d.name}</strong><p>${d.description}</p><b>${preview}</b><small>按 ${i+1} 选择</small></button>`}).join('')}</div>`;run.upgradeChoices.forEach((id,i)=>{$(`ability${i}`).onclick=()=>chooseAbility(id)})}else if(state==='character'){renderCharacterSelection({run,$,onConfirm:id=>startMission('training',run.selectionQuick,id),onCancel:cancelCharacter})}else if(state==='menu'){campaignShell.renderBase(card);$('equipmentTest').onclick=openEquipmentTest;$('dropMode').onclick=()=>{toggleDropMode()};
}else if(state==='paused'){card.innerHTML='<div class="eyebrow">EXPERIMENT PAUSED</div><h2>暂停一下，<br>思路<span>继续。</span></h2><p>实验现场已暂停，准备好后继续。</p><button id="resume" class="primary">继续实验 <span>▷</span></button><button id="back" class="back-link">结束本局…</button>';$('resume').onclick=pause;$('back').onclick=menu}else if(['dead','won'].includes(state)){renderResult(card,state==='won')}card.querySelector('button')?.focus({preventScroll:true})}
$('toggleCondenser').onclick=()=>{if(!['playing','paused','lab'].includes(run.state)||run.lab.gun.type!=='flame')return;run.condenser.toggle();syncCondenser()};
$('materialCards').addEventListener('click',e=>{const b=e.target.closest('[data-add]');if(b)move(b.dataset.add,'furnace')});$('furnaceContents').addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(b)move(b.dataset.remove,'inventory')});$('recipeCards').addEventListener('click',e=>{const b=e.target.closest('[data-recipe]');if(b&&run.state==='lab'&&!dialogType){setLabPane('craft');selected=b.dataset.recipe;syncLab()}});
$('returnAll').onclick=()=>{if(run.state==='lab'&&!dialogType){run.lab.returnAll();syncLab()}};$('craft').onclick=requestCraft;$('nextWave').onclick=()=>{if(dialogType)return;if(run.nextWave()){setSidebarTab('equipment');clearInput();sync();toast(`${gunName()} Lv.${run.lab.gun.level} · 新一关开始 · 当前生命 ${Math.ceil(run.hp)}`);$('arena').focus({preventScroll:true})}};$('ignition').onchange=()=>{if(run.state==='lab'&&!dialogType){run.lab.ignition=$('ignition').checked;syncLab()}};$('pause').onclick=pause;$('openLog').onclick=openLog;$('openArchive').onclick=openArchive;$('sound').onclick=()=>{gameAudio.setEnabled(!gameAudio.enabled);syncSound();gameAudio.play('click')};
function dragStart(e,selector,from){const b=e.target.closest(selector);if(!b||run.state!=='lab'||dialogType){e.preventDefault();return}const id=b.dataset.add||b.dataset.remove;e.dataTransfer.setData('application/x-valence',JSON.stringify({id,from}));e.dataTransfer.effectAllowed='move'}
$('materialCards').addEventListener('dragstart',e=>dragStart(e,'[data-add]','inventory'));$('furnaceContents').addEventListener('dragstart',e=>dragStart(e,'[data-remove]','furnace'));
for(const [id,to,expected]of [['furnace','furnace','inventory'],['backpack','inventory','furnace']]){const area=$(id);area.addEventListener('dragover',e=>{if(run.state==='lab'&&!dialogType){e.preventDefault();area.classList.add('drag-over')}});area.addEventListener('dragleave',()=>area.classList.remove('drag-over'));area.addEventListener('drop',e=>{e.preventDefault();area.classList.remove('drag-over');try{const data=JSON.parse(e.dataTransfer.getData('application/x-valence'));if(data.from===expected)move(data.id,to)}catch{}})}
$('dialogOverlay').addEventListener('click',e=>{if(e.target===$('dialogOverlay'))closeDialog()});
function moveJoy(e){const r=$('joystick').getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,n=Math.hypot(dx,dy),s=n>30?30/n:1;joy={x:dx*s/30,y:dy*s/30};$('stick').style.transform=`translate(${dx*s}px,${dy*s}px)`}
$('joystick').addEventListener('pointerdown',e=>{if(run.state!=='playing'||pointer!==null)return;e.preventDefault();pointer=e.pointerId;$('joystick').setPointerCapture(pointer);moveJoy(e)});$('joystick').addEventListener('pointermove',e=>{if(e.pointerId===pointer)moveJoy(e)});for(const n of ['pointerup','pointercancel','lostpointercapture'])$('joystick').addEventListener(n,e=>{if(e.pointerId===pointer)clearInput()});
window.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if(run.state==='character'&&!dialogType){if(key==='escape'){e.preventDefault();cancelCharacter()}else if(key==='tab'){const items=[...$('screenCard').querySelectorAll('button')].filter(b=>!b.disabled);if(items.length){const at=items.indexOf(document.activeElement),next=at<0?(e.shiftKey?items.length-1:0):(at+(e.shiftKey?-1:1)+items.length)%items.length;e.preventDefault();items[next].focus()}}return}if(dialogType){if(key==='escape'){e.preventDefault();closeDialog()}if(key==='tab'){const items=[...$('dialogCard').querySelectorAll('button')].filter(b=>!b.disabled);if(items.length){let at=items.indexOf(document.activeElement),next=at<0?(e.shiftKey?items.length-1:0):(at+(e.shiftKey?-1:1)+items.length)%items.length;e.preventDefault();items[next].focus()}}return}if(['arrowup','arrowdown','arrowleft','arrowright'].includes(key)&&run.state==='playing')e.preventDefault();if(e.repeat)return;if(run.state==='lab'&&['arrowleft','arrowright'].includes(key)&&!['SELECT','INPUT','TEXTAREA'].includes(e.target?.tagName)){e.preventDefault();browseRecipe(key==='arrowleft'?-1:1);return}if(run.state==='reward'&&['1','2','3'].includes(key)){e.preventDefault();selectReward(run.rewardChoices[Number(key)-1]);return}if(run.state==='upgrade'&&['1','2','3'].includes(key)){e.preventDefault();chooseAbility(run.upgradeChoices[Number(key)-1]);return}if(key==='enter'&&run.state==='menu'&&!run.runActive&&!['BUTTON','A','INPUT','TEXTAREA','SELECT'].includes(e.target?.tagName)){e.preventDefault();start();return}if(key==='escape'){pause();return}keys[key]=true});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});
function autoPause(){clearInput();if(run.state==='playing'){run.state='paused';sync()}}window.addEventListener('blur',autoPause);document.addEventListener('visibilitychange',()=>{last=performance.now();if(document.hidden)autoPause()});
function frame(now){const dt=Math.min(.05,Math.max(0,(now-last)/1000||0));last=now;run.step(dt,{viewport:$('arena').getBoundingClientRect(),x:(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+joy.x,y:(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+joy.y});gameAudio.update(run);for(const event of run.events){if(event==='clueFound')toast('已恢复维护记录 · 可在长期档案中回看');if(event==='aiCoreDropped'){toast('AI 核心已掉落 · 靠近拾取即可修复');gameAudio.play('pickup')}if(event==='aiRepaired'){toast('AI 核心接入 · 通信已恢复');gameAudio.play('craft')}if(event==='lootQueued')toast(run.lastQueued||'战利品已收纳 · 关间选择');if(event==='gunPickup')toast(run.lastPickup||'化学枪已装配');if(event==='condenserBurst')toast('水包蓄满 · 自动向侧后方喷水！');if(event==='elite')toast('精英'+(run.enemies.find(e=>e.special&&e.elite&&e.hp>0)?.displayName||ENEMY_TYPES[WAVE_NEW_TYPES[run.wave-1]].name)+' · 高速 / 高伤 / 高频攻击');if(event==='finalTransform')toast(run.missionId==='core'?'ERROR // 识别协议失效':'形态转换 · '+FORM_NAMES[(run.enemies.find(e=>e.type===6)?.phase||1)-1]);if(event==='boss')toast(run.enemies.find(e=>e.special&&e.hp>0)?.displayName||(run.mission?.bossName||'失控反应釜出现 · 注意预警'));if(event==='bossRing')toast('高压冲击：移向绿色缺口，避开冲击弧');if(event==='bossZone')toast('危险区域已标记 · 注意预警并寻找安全路线');if(event==='overdrive')toast('首领进入高压阶段 · 注意连续攻击');if(event==='hurt'){renderer.shake=10;}}run.events=[];if(run.state!=='lab')renderer.draw(run,now/1000);sync();if(now>toastUntil)$('toast').classList.add('hidden');requestAnimationFrame(frame)}
setSidebarTab('equipment');sync();requestAnimationFrame(frame);
